import React, {
  useCallback,
  useEffect,
  useLayoutEffect,
  memo,
  useMemo,
  useRef,
  useState,
} from 'react';
import cx from 'classnames';
import {
  DialogState,
  ExpertReference,
  Medium,
  Memori,
  Message,
  Tenant,
  User,
} from '@memori.ai/memori-api-client/dist/types';
import { hasTouchscreen } from '../../helpers/utils';
import { getResourceUrl } from '../../helpers/media';
import ChatBubble from '../ChatBubble/ChatBubble';
import MediaWidget, {
  Props as MediaWidgetProps,
} from '../MediaWidget/MediaWidget';
import { Props as MemoriProps } from '../MemoriWidget/MemoriWidget';
import memoriApiClient from '@memori.ai/memori-api-client';
import ChatInputs from '../ChatInputs/ChatInputs';
import Typing from '../Typing/Typing';
import { boardOfExpertsLoadingSentences } from '../../helpers/constants';
import { ChevronDown, FileText as DocumentIcon } from 'lucide-react';
import {
  getNextPinnedToBottom,
  isChatScrolledToBottom,
  scrollChatToBottom,
} from '../../helpers/chatScroll';
import { useTranslation } from 'react-i18next';
import { Tooltip, Modal } from '@memori.ai/ui';
import {
  maxDocumentsPerMessage,
  maxDocumentContentLength,
  pasteAsCardLineThreshold,
  pasteAsCardCharThreshold,
} from '../../helpers/constants';
import {
  BADGE_EMOJI,
  buildLlmUsageHtml,
  formatDuration,
  formatImpactWithApiUnit,
  formatCacheHitPercent,
  formatIntegerValue,
  getCacheHitPercent,
  getImpactComparison,
  getMetricValue,
  LlmUsageLabels,
  LlmUsageOnLine,
  UsageBadgeType,
} from '../../helpers/llmUsage';

const CODE_MIME_TYPES = [
  'text/javascript',
  'text/ecmascript',
  'application/json',
  'text/css',
  'application/xml',
  'application/x-sh',
  'text/x-python',
  'text/x-c++src',
  'application/x-php',
  'text/x-ruby',
  'text/x-sql',
];
export interface Props {
  memori: Memori;
  tenant?: Tenant;
  sessionID: string;
  translateTo?: string;
  baseUrl?: string;
  apiUrl?: string;
  memoriTyping?: boolean;
  typingText?: string;
  showTypingText?: boolean;
  history: Message[];
  authToken?: string;
  dialogState?: DialogState;
  pushMessage: (message: Message) => void;
  simulateUserPrompt: (text: string, translatedText?: string) => void;
  showDates?: boolean;
  showUpload?: boolean;
  showContextPerLine?: boolean;
  showAIicon?: boolean;
  showTranslationOriginal?: boolean;
  showWhyThisAnswer?: boolean;
  showReasoning?: boolean;
  showMessageConsumption?: boolean;
  client?: ReturnType<typeof memoriApiClient>;
  preview?: boolean;
  microphoneMode?: 'CONTINUOUS' | 'HOLD_TO_TALK';
  sendOnEnter?: 'keypress' | 'click';
  setSendOnEnter: (sendOnEnter: 'keypress' | 'click') => void;
  attachmentsMenuOpen?: 'link' | 'media';
  setAttachmentsMenuOpen: (attachmentsMenuOpen: 'link' | 'media') => void;
  instruct?: boolean;
  showCopyButton?: boolean;
  showInputs?: boolean;
  showMicrophone?: boolean;
  userMessage?: string;
  onChangeUserMessage: (userMessage: string) => void;
  sendMessage: (msg: string, media?: (Medium & { type: string })[]) => void;
  /** Sync engine dialog state after MediumSelected (keeps catch-up fingerprints accurate). */
  onMediumSelectedState?: (state: DialogState) => void;
  listening?: boolean;
  setEnableFocusChatInput: (enableFocusChatInput: boolean) => void;
  isPlayingAudio?: boolean;
  stopAudio: () => void;
  startListening: () => void | Promise<boolean>;
  stopListening: (onTranscript?: (text: string) => void) => void;
  audioStream?: MediaStream | null;
  transcribing?: boolean;
  customMediaRenderer?: MediaWidgetProps['customMediaRenderer'];
  layout?: MemoriProps['layout'];
  userAvatar?: MemoriProps['userAvatar'];
  user?: User;
  experts?: ExpertReference[];
  useMathFormatting?: boolean;
  isHistoryView?: boolean;
  isChatlogPanel?: boolean;
  showFunctionCache?: boolean;
  /** Override total document payload and per-document content limit (character count). */
  maxTotalMessagePayload?: number;
  /** Max characters in chat textarea; shows counter and enforces paste + existing text does not exceed this limit. */
  maxTextareaCharacters?: number;
  /** Max attachments (docs + images) per message. */
  /** Integration global background image URL applied to `.memori-chat--content`. */
  globalBackground?: string;
  /** Optional branding node for the conversation footer row. */
  footerBrand?: React.ReactNode;
  /** When false, hides the AI disclaimer in the footer. */
  showAiGeneratedNote?: boolean;
}

type MessageWithLlmUsage = Message & { llmUsage?: LlmUsageOnLine };
interface UsageBadgeModalState {
  type: UsageBadgeType;
  usage: LlmUsageOnLine;
}

const Chat: React.FC<Props> = ({
  memori,
  tenant,
  sessionID,
  baseUrl,
  apiUrl,
  client,
  translateTo,
  memoriTyping,
  typingText,
  showTypingText = false,
  history = [],
  authToken,
  dialogState,
  simulateUserPrompt,
  showDates = false,
  showContextPerLine = false,
  showAIicon = true,
  showWhyThisAnswer = true,
  showCopyButton = true,
  showTranslationOriginal = false,
  showReasoning = false,
  showMessageConsumption = false,
  preview = false,
  instruct = false,
  showInputs = true,
  showMicrophone = false,
  microphoneMode = 'HOLD_TO_TALK',
  sendOnEnter,
  setSendOnEnter,
  attachmentsMenuOpen,
  setAttachmentsMenuOpen,
  userMessage = '',
  onChangeUserMessage,
  sendMessage,
  onMediumSelectedState,
  listening,
  setEnableFocusChatInput,
  isPlayingAudio,
  stopAudio,
  startListening,
  stopListening,
  audioStream,
  transcribing,
  customMediaRenderer,
  user,
  userAvatar,
  showUpload = false,
  experts,
  useMathFormatting = false,
  isHistoryView = false,
  isChatlogPanel = false,
  showFunctionCache = false,
  maxTotalMessagePayload,
  maxTextareaCharacters,
  globalBackground,
  footerBrand,
  showAiGeneratedNote = true,
}) => {
  const [isTextareaExpanded, setIsTextareaExpanded] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [showJumpToLatest, setShowJumpToLatest] = useState(false);
  const [activeUsageBadge, setActiveUsageBadge] =
    useState<UsageBadgeModalState | null>(null);
  const chatWrapperRef = useRef<HTMLDivElement>(null);
  const chatContentRef = useRef<HTMLDivElement>(null);
  const isPinnedToBottomRef = useRef(true);
  const lastScrollTopRef = useRef(0);
  const prevHistoryLengthRef = useRef(history.length);
  const { t } = useTranslation();
  const locale = (translateTo || memori.culture || 'it-IT').replace('_', '-');

  const llmUsageLabels = useMemo<LlmUsageLabels>(
    () => ({
      llm: t('chatLogs.llm', { defaultValue: 'LLM' }),
      model: t('chatLogs.model', { defaultValue: 'Model' }),
      provider: t('chatLogs.provider', { defaultValue: 'Provider' }),
      tokens: t('chatLogs.tokens', { defaultValue: 'Tokens' }),
      input: t('chatLogs.input', { defaultValue: 'Input' }),
      output: t('chatLogs.output', { defaultValue: 'Output' }),
      cacheRead: t('chatLogs.cacheRead', { defaultValue: 'Cache read' }),
      cacheWrite: t('chatLogs.cacheWrite', { defaultValue: 'Cache write' }),
      cacheHit: t('chatLogs.cacheHit', { defaultValue: 'Cache hit' }),
      duration: t('chatLogs.duration', { defaultValue: 'Duration' }),
      energy: t('chatLogs.energy', { defaultValue: 'Energy' }),
      co2: t('chatLogs.co2', { defaultValue: 'CO2' }),
      water: t('chatLogs.water', { defaultValue: 'Water' }),
      usageBadgesHint: t('chatLogs.usageBadgesHint', {
        defaultValue: 'Click one of these buttons to show more information',
      }),
    }),
    [t]
  );

  const usageHtmlByIndex = useMemo(
    () =>
      history.map((message, index) => {
        const messageWithUsage = message as MessageWithLlmUsage;
        return showMessageConsumption &&
          !message.fromUser &&
          messageWithUsage.llmUsage
          ? buildLlmUsageHtml(
              messageWithUsage.llmUsage,
              llmUsageLabels,
              index,
              locale
            )
          : '';
      }),
    [history, llmUsageLabels, locale, showMessageConsumption]
  );

  const activeCacheUsage =
    activeUsageBadge?.type === 'llm' ? activeUsageBadge.usage : undefined;
  const activeCacheReadTokens = activeCacheUsage?.inputCacheReadTokens ?? 0;
  const activeCacheWriteTokens = activeCacheUsage?.inputCacheWriteTokens ?? 0;
  const activeLlmCacheHitPercent =
    activeCacheReadTokens > 0
      ? getCacheHitPercent(
          activeCacheReadTokens,
          activeCacheUsage?.totalInputTokens
        )
      : undefined;

  const enteringMessageIndexRef = useRef<number | null>(null);
  if (history.length === prevHistoryLengthRef.current + 1) {
    enteringMessageIndexRef.current =
      isHistoryView || isChatlogPanel || preview ? null : history.length - 1;
  } else if (history.length !== prevHistoryLengthRef.current) {
    enteringMessageIndexRef.current = null;
  }

  useLayoutEffect(() => {
    prevHistoryLengthRef.current = history.length;
  }, [history.length]);

  const enteringMessageIndex = enteringMessageIndexRef.current;

  const scrollToBottom = useCallback(() => {
    if (preview || isHistoryView) return;
    const content = chatContentRef.current;
    if (!content) return;
    scrollChatToBottom(content);
    lastScrollTopRef.current = content.scrollTop;
  }, [isHistoryView, preview]);

  const requestScrollToBottom = useCallback(() => {
    isPinnedToBottomRef.current = true;
    scrollToBottom();
  }, [scrollToBottom]);

  const handleSendMessage = useCallback(
    (msg: string, media?: (Medium & { type: string })[]) => {
      requestScrollToBottom();
      sendMessage(msg, media);
    },
    [requestScrollToBottom, sendMessage]
  );

  const handleSimulateUserPrompt = useCallback(
    (text: string, translatedText?: string) => {
      requestScrollToBottom();
      simulateUserPrompt(text, translatedText);
    },
    [requestScrollToBottom, simulateUserPrompt]
  );

  const updateJumpToLatestVisibility = useCallback(() => {
    const content = chatContentRef.current;
    if (!content || preview || isHistoryView) {
      setShowJumpToLatest(false);
      return;
    }
    setShowJumpToLatest(!isChatScrolledToBottom(content));
  }, [isHistoryView, preview]);

  const followLatestIfPinned = useCallback(() => {
    if (isPinnedToBottomRef.current) scrollToBottom();
    updateJumpToLatestVisibility();
  }, [scrollToBottom, updateJumpToLatestVisibility]);

  useLayoutEffect(() => {
    followLatestIfPinned();
  }, [history, memoriTyping, typingText, followLatestIfPinned]);

  useEffect(() => {
    const content = chatContentRef.current;
    if (!content) return;
    const onScroll = () => {
      isPinnedToBottomRef.current = getNextPinnedToBottom(
        isPinnedToBottomRef.current,
        lastScrollTopRef.current,
        content
      );
      lastScrollTopRef.current = content.scrollTop;
      updateJumpToLatestVisibility();
    };
    content.addEventListener('scroll', onScroll, { passive: true });
    updateJumpToLatestVisibility();
    return () => content.removeEventListener('scroll', onScroll);
  }, [updateJumpToLatestVisibility]);

  // Content keeps growing after render (images, markdown, typing text, hints),
  // so keep following it while the user is pinned to the bottom.
  useEffect(() => {
    const content = chatContentRef.current;
    if (
      !content ||
      typeof ResizeObserver === 'undefined' ||
      typeof MutationObserver === 'undefined'
    )
      return;

    const resizeObserver = new ResizeObserver(() => followLatestIfPinned());
    resizeObserver.observe(content);
    Array.from(content.children).forEach(child =>
      resizeObserver.observe(child)
    );

    const mutationObserver = new MutationObserver(mutations => {
      mutations.forEach(mutation => {
        mutation.addedNodes.forEach(node => {
          if (node instanceof Element) resizeObserver.observe(node);
        });
        mutation.removedNodes.forEach(node => {
          if (node instanceof Element) resizeObserver.unobserve(node);
        });
      });
    });
    mutationObserver.observe(content, { childList: true });

    return () => {
      mutationObserver.disconnect();
      resizeObserver.disconnect();
    };
  }, [followLatestIfPinned]);

  const onTextareaFocus = () => {
    stopListening();
    const hasTouch = hasTouchscreen();

    if (hasTouch) setEnableFocusChatInput(true);
  };
  const onTextareaBlur = () => {
    if (
      document
        .getElementById('chat-wrapper')
        ?.classList?.contains('chat-focused')
    ) {
      document.getElementById('chat-wrapper')?.classList.remove('chat-focused');
      document
        .querySelector('.memori.memori-widget')
        ?.classList?.remove('chat-focused');
    }
  };

  const onTextareaExpanded = (expanded: boolean) => {
    setIsTextareaExpanded(expanded);
  };

  // Drag and drop handlers for overlay
  useEffect(() => {
    // Only enable drag and drop when showUpload is true
    if (!showUpload) return;

    let dragCounter = 0;
    const chatWrapper = document.getElementById('chat-wrapper');

    const handleDragEnter = (e: DragEvent) => {
      // Only show overlay if dragging files (not text/links)
      if (e.dataTransfer?.types.includes('Files')) {
        dragCounter++;
        if (dragCounter === 1) {
          setIsDragging(true);
        }
      }
    };

    const handleDragLeave = (e: DragEvent) => {
      if (e.dataTransfer?.types.includes('Files')) {
        dragCounter--;
        if (dragCounter === 0) {
          setIsDragging(false);
        }
      }
    };

    const handleDragOver = (e: DragEvent) => {
      // Prevent default to allow drop, but don't stop propagation
      if (e.dataTransfer?.types.includes('Files')) {
        e.preventDefault();
      }
    };

    const handleDrop = (e: DragEvent) => {
      // Reset dragging state, but let UploadButton handle the actual drop
      if (e.dataTransfer?.types.includes('Files')) {
        dragCounter = 0;
        setIsDragging(false);
      }
    };

    if (chatWrapper) {
      chatWrapper.addEventListener('dragenter', handleDragEnter);
      chatWrapper.addEventListener('dragleave', handleDragLeave);
      chatWrapper.addEventListener('dragover', handleDragOver);
      chatWrapper.addEventListener('drop', handleDrop);
    }

    return () => {
      if (chatWrapper) {
        chatWrapper.removeEventListener('dragenter', handleDragEnter);
        chatWrapper.removeEventListener('dragleave', handleDragLeave);
        chatWrapper.removeEventListener('dragover', handleDragOver);
        chatWrapper.removeEventListener('drop', handleDrop);
      }
    };
  }, [showUpload]);

  useEffect(() => {
    const wrapper = chatWrapperRef.current;
    if (!wrapper || !showMessageConsumption) return;

    const handleUsageBadgeClick = (event: MouseEvent) => {
      const target = event.target as HTMLElement | null;
      const button = target?.closest<HTMLElement>(
        '[data-llm-badge-type][data-line-index]'
      );
      if (!button) return;

      const lineIndex = Number(button.dataset.lineIndex);
      const badgeType = button.dataset.llmBadgeType as
        | UsageBadgeType
        | undefined;
      if (!Number.isInteger(lineIndex) || !badgeType) return;

      const line = (history?.[lineIndex] as MessageWithLlmUsage) ?? null;
      if (!line?.llmUsage) return;

      event.preventDefault();
      setActiveUsageBadge({
        type: badgeType,
        usage: line.llmUsage,
      });
    };

    wrapper.addEventListener('click', handleUsageBadgeClick);
    return () => {
      wrapper.removeEventListener('click', handleUsageBadgeClick);
    };
  }, [history, showMessageConsumption]);

  return (
    <div
      ref={chatWrapperRef}
      className={cx('memori-chat--wrapper', {
        'memori-chat-wrapper--translate': translateTo,
        'memori-chat-wrapper--expanded': isTextareaExpanded,
        'memori-chat-wrapper--dragging': isDragging,
      })}
      id="chat-wrapper"
      lang={translateTo?.toUpperCase()}
      data-memori-lang={memori.culture?.split('-')?.[0]?.toUpperCase() ?? 'EN'}
    >
      {/* Drag and drop overlay */}
      {isDragging && (
        <div className="memori-chat--drag-overlay">
          <DocumentIcon className="memori-chat--drag-overlay-icon" />
          <span className="memori-chat--drag-overlay-text">
            {t('upload.dragAndDropFiles') ??
              'Drag and drop files here to add them to the chat'}
          </span>
        </div>
      )}
      <div
        className={cx({ 'memori-conversation-column': showInputs })}
        style={showInputs ? undefined : { display: 'contents' }}
      >
        <div
          className={cx('memori-chat--history', {
            'memori-chat--history-touch': hasTouchscreen(),
            'memori-chat--history--has-global-background': !!globalBackground,
          })}
          style={
            globalBackground
              ? ({
                  ['--memori-chat-global-background' as string]: `url(${globalBackground})`,
                } as React.CSSProperties)
              : undefined
          }
        >
          <div
            ref={chatContentRef}
            className={cx('memori-chat--content', {
              'memori-chat--content-touch': hasTouchscreen(),
              'memori-chat--content--has-global-background': !!globalBackground,
            })}
          >
            <div
              className={cx('memori-chat--cover')}
              style={{
                backgroundImage: `url("${getResourceUrl({
                  type: 'cover',
                  tenantID: tenant?.name,
                  resourceURI: memori.coverURL,
                  baseURL: baseUrl,
                  apiURL: apiUrl,
                })}"), url("${getResourceUrl({
                  type: 'cover',
                  tenantID: tenant?.name,
                  baseURL: baseUrl || 'https://www.aisuru.com',
                  apiURL: apiUrl,
                })}")`,
              }}
            />

            {history.map((message, index) => (
              <React.Fragment
                key={`${index}-${
                  message.text?.includes('<document_attachment')
                    ? 'has-attachments'
                    : 'no-attachments'
                }-${message.timestamp}`}
              >
                <div
                // style={{
                //   marginBottom: index === history.length - 1 ? '24px' : 0,
                // }}
                >
                  <ChatBubble
                    key={`chatbubble-${index}-${
                      message.text?.includes('<document_attachment')
                        ? 'has-attachments'
                        : 'no-attachments'
                    }-${message.timestamp}`}
                    isFirst={index === 0}
                    message={message}
                    memori={memori}
                    tenant={tenant}
                    client={client}
                    customMediaRenderer={customMediaRenderer}
                    translateTo={translateTo}
                    baseUrl={baseUrl}
                    apiUrl={apiUrl}
                    sessionID={sessionID}
                    simulateUserPrompt={handleSimulateUserPrompt}
                    showAIicon={showAIicon}
                    showWhyThisAnswer={showWhyThisAnswer}
                    codeMimeTypes={CODE_MIME_TYPES}
                    showTranslationOriginal={showTranslationOriginal}
                    showFeedback={
                      index === history.length - 1 &&
                      !message.fromUser &&
                      dialogState?.acceptsFeedback
                    }
                    user={user}
                    userAvatar={userAvatar}
                    experts={experts}
                    showCopyButton={showCopyButton}
                    useMathFormatting={useMathFormatting}
                    showFunctionCache={showFunctionCache}
                    showReasoning={showReasoning}
                    usageHtml={usageHtmlByIndex[index]}
                    isChatlogPanel={isChatlogPanel}
                    // Chat history / chatlog panel always shows timestamps;
                    // live chat still respects the consumer showDates prop.
                    showDates={showDates || isChatlogPanel}
                    animateEnter={index === enteringMessageIndex}
                  />

                  {showContextPerLine &&
                    !!Object.keys(message.contextVars ?? {}).length && (
                      <div className="memori-chat--context-vars">
                        {Object.keys(message.contextVars ?? {}).map(key =>
                          message.contextVars?.[key] === '-' ? (
                            <div
                              className={`memori-chat--context-tag memori-chat--context-tag-canceled`}
                              key={key}
                            >
                              <span className="memori-chat--context-tag-text">
                                {key}
                              </span>
                            </div>
                          ) : message.contextVars?.[key] === '✔️' ? (
                            <div className="memori-chat--context-tag" key={key}>
                              <span className="memori-chat--context-tag-text">
                                {key}
                              </span>
                            </div>
                          ) : (
                            <div className="memori-chat--context-tag" key={key}>
                              <span className="memori-chat--context-tag-text">
                                {key}: {message.contextVars?.[key]}
                              </span>
                            </div>
                          )
                        )}
                      </div>
                    )}
                </div>
              </React.Fragment>
            ))}

            {dialogState?.hints &&
              dialogState.hints.length > 0 &&
              !memoriTyping && (
                <MediaWidget
                  simulateUserPrompt={handleSimulateUserPrompt}
                  hints={
                    dialogState.translatedHints
                      ? dialogState.translatedHints
                      : dialogState.hints.map(h => ({
                          text: h,
                          originalText: h,
                        }))
                  }
                />
              )}

            {!!memoriTyping && (
              <Typing
                useDefaultSentences={showTypingText}
                lang={
                  translateTo
                    ? translateTo.toLowerCase() === 'it'
                      ? 'it'
                      : 'en'
                    : memori.culture?.split('-')?.[0]?.toLowerCase() === 'it'
                      ? 'it'
                      : 'en'
                }
                sentence={typingText}
                memori={memori}
                tenant={tenant}
                baseUrl={baseUrl}
                apiUrl={apiUrl}
                experts={experts}
                sentences={
                  memori.enableBoardOfExperts
                    ? boardOfExpertsLoadingSentences
                    : undefined
                }
                key={typingText}
              />
            )}
            <div id="end-messages-ref" />
          </div>
          {showJumpToLatest && (
            <div className="memori-chat--jump-to-latest">
              <button
                type="button"
                className="memori-chat--jump-to-latest-btn"
                data-testid="memori-chat-jump-to-latest"
                aria-label={
                  t('scrollToLatest', {
                    defaultValue: 'Scroll to latest',
                  }) || 'Scroll to latest'
                }
                onClick={() => {
                  requestScrollToBottom();
                  updateJumpToLatestVisibility();
                }}
              >
                {memoriTyping ? (
                  <span
                    className="memori-chat--jump-to-latest-typing"
                    data-testid="memori-chat-jump-to-latest-typing"
                    aria-hidden
                  >
                    <span className="memori-chat--jump-to-latest-typing-dot" />
                    <span className="memori-chat--jump-to-latest-typing-dot" />
                    <span className="memori-chat--jump-to-latest-typing-dot" />
                  </span>
                ) : (
                  <ChevronDown aria-hidden size={20} />
                )}
              </button>
            </div>
          )}
        </div>

        {showInputs && (
          <ChatInputs
            userMessage={userMessage}
            onChangeUserMessage={onChangeUserMessage}
            dialogState={dialogState}
            instruct={instruct}
            authToken={authToken}
            sendMessage={handleSendMessage}
            isTyping={memoriTyping}
            microphoneMode={microphoneMode}
            sendOnEnter={sendOnEnter}
            setSendOnEnter={setSendOnEnter}
            client={client}
            sessionID={sessionID}
            baseUrl={baseUrl}
            showUpload={showUpload}
            onMediumSelectedState={onMediumSelectedState}
            attachmentsMenuOpen={attachmentsMenuOpen}
            setAttachmentsMenuOpen={setAttachmentsMenuOpen}
            onTextareaFocus={onTextareaFocus}
            onTextareaBlur={onTextareaBlur}
            onTextareaExpanded={onTextareaExpanded}
            startListening={startListening}
            stopListening={stopListening}
            audioStream={audioStream}
            transcribing={transcribing}
            stopAudio={stopAudio}
            listening={listening}
            isPlayingAudio={isPlayingAudio}
            showMicrophone={showMicrophone}
            memoriID={memori?.memoriID}
            maxTotalMessagePayload={maxTotalMessagePayload}
            maxTextareaCharacters={maxTextareaCharacters}
            maxDocumentsPerMessage={maxDocumentsPerMessage}
            maxDocumentContentLength={maxDocumentContentLength}
            pasteAsCardLineThreshold={pasteAsCardLineThreshold}
            pasteAsCardCharThreshold={pasteAsCardCharThreshold}
            showAiGeneratedNote={showAiGeneratedNote}
            footerBrand={footerBrand}
          />
        )}
      </div>

      <Modal
        open={!!activeUsageBadge}
        onClose={() => setActiveUsageBadge(null)}
        title={
          activeUsageBadge?.type
            ? `${BADGE_EMOJI[activeUsageBadge.type]} ${
                llmUsageLabels[activeUsageBadge.type]
              }`
            : undefined
        }
        className="memori-chat--usage-modal"
        width="30rem"
        stacking="stacked"
      >
        {activeUsageBadge?.type === 'llm' && (
          <dl className="memori-chat--usage-details">
            <div>
              <dt>{llmUsageLabels.provider}</dt>
              <dd>{activeUsageBadge.usage.provider ?? '—'}</dd>
            </div>
            <div>
              <dt>{llmUsageLabels.model}</dt>
              <dd>{activeUsageBadge.usage.model ?? '—'}</dd>
            </div>
            <div>
              <dt>
                {llmUsageLabels.tokens} {llmUsageLabels.input}
              </dt>
              <dd>
                {formatIntegerValue(
                  activeUsageBadge.usage.totalInputTokens ?? 0,
                  locale
                )}
              </dd>
            </div>
            <div>
              <dt>
                {llmUsageLabels.tokens} {llmUsageLabels.output}
              </dt>
              <dd>
                {formatIntegerValue(
                  activeUsageBadge.usage.outputTokens ?? 0,
                  locale
                )}
              </dd>
            </div>
            {activeCacheReadTokens > 0 && (
              <div>
                <dt>{llmUsageLabels.cacheRead}</dt>
                <dd>{formatIntegerValue(activeCacheReadTokens, locale)}</dd>
              </div>
            )}
            {activeCacheWriteTokens > 0 && (
              <div>
                <dt>{llmUsageLabels.cacheWrite}</dt>
                <dd>{formatIntegerValue(activeCacheWriteTokens, locale)}</dd>
              </div>
            )}
            {activeLlmCacheHitPercent !== undefined && (
              <div>
                <dt>{llmUsageLabels.cacheHit}</dt>
                <dd>
                  {formatCacheHitPercent(activeLlmCacheHitPercent, locale)}
                </dd>
              </div>
            )}
          </dl>
        )}

        {activeUsageBadge?.type === 'energy' && (
          <div className="memori-chat--usage-educational-content">
            <strong className="memori-chat--usage-metric-value">
              {formatImpactWithApiUnit(
                getMetricValue(activeUsageBadge.usage.energyImpact?.energy) ??
                  0,
                activeUsageBadge.usage.energyImpact?.energyUnit,
                'kWh',
                'energy',
                locale
              )}
            </strong>
            <Tooltip
              content={t('chatLogs.approximateValuesTooltip', {
                defaultValue: 'These values are approximate.',
              })}
            >
              <p className="memori-chat--usage-comparable">
                {getImpactComparison(
                  getMetricValue(activeUsageBadge.usage.energyImpact?.energy) ??
                    0,
                  'energy',
                  locale,
                  t
                )}
              </p>
            </Tooltip>
            <p>{t('chatLogs.energyImpactDescription')}</p>
          </div>
        )}
        {activeUsageBadge?.type === 'co2' && (
          <div className="memori-chat--usage-educational-content">
            <strong className="memori-chat--usage-metric-value">
              {formatImpactWithApiUnit(
                getMetricValue(activeUsageBadge.usage.energyImpact?.gwp) ?? 0,
                activeUsageBadge.usage.energyImpact?.gwpUnit,
                'kgCO2eq',
                'co2',
                locale
              )}
            </strong>
            <Tooltip
              content={t('chatLogs.approximateValuesTooltip', {
                defaultValue: 'These values are approximate.',
              })}
            >
              <p className="memori-chat--usage-comparable">
                {getImpactComparison(
                  getMetricValue(activeUsageBadge.usage.energyImpact?.gwp) ?? 0,
                  'co2',
                  locale,
                  t
                )}
              </p>
            </Tooltip>
            <p>{t('chatLogs.co2ImpactDescription')}</p>
          </div>
        )}
        {activeUsageBadge?.type === 'water' && (
          <div className="memori-chat--usage-educational-content">
            <strong className="memori-chat--usage-metric-value">
              {formatImpactWithApiUnit(
                getMetricValue(activeUsageBadge.usage.energyImpact?.wcf) ?? 0,
                activeUsageBadge.usage.energyImpact?.wcfUnit,
                'L',
                'water',
                locale
              )}
            </strong>
            <Tooltip
              content={t('chatLogs.approximateValuesTooltip', {
                defaultValue: 'These values are approximate.',
              })}
            >
              <p className="memori-chat--usage-comparable">
                {getImpactComparison(
                  getMetricValue(activeUsageBadge.usage.energyImpact?.wcf) ?? 0,
                  'water',
                  locale,
                  t
                )}
              </p>
            </Tooltip>
            <p>{t('chatLogs.waterImpactDescription')}</p>
          </div>
        )}
      </Modal>
    </div>
  );
};

export default memo(Chat);
